from django import template
from django.template.base import token_kwargs
from djinn.core.cva import cva

register = template.Library()

form_field_cva = cva(
    base="grid w-full max-w-sm gap-1.5",
    variants={
        "variant": {
            "default": "",
            "error": "",
        },
    },
    default_variants={
        "variant": "default",
    }
)

class FormFieldNode(template.Node):
    def __init__(self, nodelist, kwargs):
        self.nodelist = nodelist
        self.kwargs = kwargs

    def render(self, context):
        resolved_kwargs = {}
        for k, v in self.kwargs.items():
            try:
                resolved_kwargs[k] = v.resolve(context)
            except template.VariableDoesNotExist:
                resolved_kwargs[k] = ""

        final_class = form_field_cva(**resolved_kwargs)

        # Input-specific classes (separate from wrapper classes)
        input_variant = resolved_kwargs.get("variant", "default")
        input_class = "border-destructive" if input_variant == "error" else ""

        known_args = ["variant", "label", "error", "help_text", "type", "name", "id", "value", "disabled", "required", "placeholder", "class", "class_name", "input_class"]
        attrs = {k: v for k, v in resolved_kwargs.items() if k not in known_args}

        t = context.template.engine.get_template('components/form-field.html')
        new_context = context.new({
            "class": final_class,
            "input_class": input_class,
            "attrs": attrs,
            **resolved_kwargs
        })
        return t.render(new_context)

@register.tag('djinn_form_field')
def djinn_form_field(parser, token):
    bits = token.split_contents()
    kwargs = token_kwargs(bits[1:], parser)
    nodelist = parser.parse(('enddjinn_form_field',))
    parser.delete_first_token()
    return FormFieldNode(nodelist, kwargs)
